package com.team2.wellness.engagement.recap.domain;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="monthly_recaps",uniqueConstraints=@UniqueConstraint(name="uk_monthly_recaps_group_month",columnNames={"group_id","recap_month"})) public class MonthlyRecap { @Id private UUID id; @Column(name="group_id",nullable=false) private UUID groupId; @Convert(converter=YearMonthAttributeConverter.class) @Column(name="recap_month",nullable=false) private YearMonth recapMonth; @Column(nullable=false,columnDefinition="text") private String summary; @Column(name="image_object_key") private String imageObjectKey; @Column(name="created_at",nullable=false) private Instant createdAt; protected MonthlyRecap(){} public MonthlyRecap(UUID g,YearMonth m,String s){id=UUID.randomUUID();groupId=g;recapMonth=m;summary=s;createdAt=Instant.now();} public void attachImage(String key){imageObjectKey=key;} public UUID getId(){return id;} public UUID getGroupId(){return groupId;} public YearMonth getRecapMonth(){return recapMonth;} public String getSummary(){return summary;} public String getImageObjectKey(){return imageObjectKey;} }
